shader.source:
struct VS_INPUT
{
    float4 a_position : POSITION;
    float3 a_normal   : NORMAL;
    float2 a_texcoord : TEXCOORD0;
};

struct VS_OUTPUT
{
    float4 v_position : POSITION;
    float3 v_normal   : NORMAL;
    float2 v_texcoord : TEXCOORD0;
};

float time;
float2 resolution;
float2 mouse;
float3 spectrum;
float4x4 mvp;

VS_OUTPUT vs_main(in VS_INPUT In)
{
    VS_OUTPUT Out;
    Out.v_position = mul(mvp, In.a_position);
    Out.v_normal   = In.a_normal;
    Out.v_texcoord = In.a_texcoord;
    return Out;
}

#version 310 es
#extension GL_EXT_shader_io_blocks: enable

uniform float time;
uniform vec2 resolution;
uniform vec2 mouse;
uniform vec3 spectrum;
uniform mat4 mvp;

in vec4 a_position;
in vec3 a_normal;
in vec2 a_texcoord;

out VertexData
{
    vec4 v_position;
    vec3 v_normal;
    vec2 v_texcoord;
} outData;

void main(void)
{
    // Some drivers don't like position being written here
    // with the tessellation stages enabled also.
    // Comment next line when Tess.Eval shader is enabled.
    gl_Position = mvp * a_position;

    outData.v_position = a_position;
    outData.v_normal = a_normal;
    outData.v_texcoord = a_texcoord;
}

uniform float time;
uniform vec2 resolution;
uniform vec2 mouse;
uniform vec3 spectrum;
uniform mat4 mvp;

attribute vec4 a_position;
attribute vec3 a_normal;
attribute vec2 a_texcoord;

varying vec3 v_normal;
varying vec2 v_texcoord;

void main(void)
{
    gl_Position = mvp * a_position;
    v_normal    = a_normal;
    v_texcoord  = a_texcoord;
}

