#include <metal_stdlib>
using namespace metal;

struct VS_INPUT
{
    float4 a_position [[attribute(0)]];
    float3 a_normal   [[attribute(1)]];
    float2 a_texcoord [[attribute(2)]];
};

struct VS_OUTPUT
{
    float4 v_position [[position]];
    float3 v_normal;
    float2 v_texcoord;
};

struct VS_UNIFORM
{
    float time;
    float2 resolution;
    float2 mouse;
    float3 spectrum;
    float4x4 mvp;
};

vertex
VS_OUTPUT vs_main(
    VS_INPUT input [[stage_in]],
    constant VS_UNIFORM& uniform [[buffer(16)]])
{
    VS_OUTPUT out;
    out.v_position = uniform.mvp * input.a_position;
    out.v_normal   = input.a_normal;
    out.v_texcoord = input.a_texcoord;
    return out;
}

#version 310 es
#extension GL_EXT_shader_io_blocks: enable
#extension GL_EXT_tessellation_shader: enable

layout(vertices = 3) out;

in VertexData
{
    vec4 v_position;
    vec3 v_normal;
    vec2 v_texcoord;
} inData[];

out VertexData
{
    vec4 v_position;
    vec3 v_normal;
    vec2 v_texcoord;
} outData[];

const float TessLevelInner = 1.;
const float TessLevelOuter = 1.;

#define ID gl_InvocationID

uniform float time;
uniform vec2 resolution;
uniform vec2 mouse;
uniform vec3 spectrum;

void main()
{
    outData[ID].v_position = inData[ID].v_position;
    outData[ID].v_normal = inData[ID].v_normal;
    outData[ID].v_texcoord = inData[ID].v_texcoord;

    if(ID == 0)
    {
        gl_TessLevelInner[0] = TessLevelInner;
        gl_TessLevelOuter[0] = TessLevelOuter;
        gl_TessLevelOuter[1] = TessLevelOuter;
        gl_TessLevelOuter[2] = TessLevelOuter;
    }
}

