    EndPrimitive();
}

struct PS_INPUT
{
    float3 v_normal   : NORMAL;
    float2 v_texcoord : TEXCOORD0;
};

struct PS_OUTPUT
{
    float4 color : COLOR0;
};

float time;
float2 resolution;
float2 mouse;
float3 spectrum;

sampler2D texture0;
sampler2D texture1;
sampler2D texture2;
sampler2D texture3;
sampler2D prevFrame;
sampler2D prevPass;

PS_OUTPUT ps_main(in PS_INPUT In)
{
    PS_OUTPUT Out;
    Out.color = float4(1.,1.,1.,1.);
    return Out;
}

#version 310 es
#extension GL_EXT_shader_io_blocks: enable

precision highp float;

uniform float time;
uniform vec2 resolution;
uniform vec2 mouse;
uniform vec3 spectrum;

uniform sampler2D texture0;
uniform sampler2D texture1;
uniform sampler2D texture2;
uniform sampler2D texture3;
uniform sampler2D prevFrame;
uniform sampler2D prevPass;

in VertexData
{
    vec4 v_position;
    vec3 v_normal;
    vec2 v_texcoord;
} inData;

out vec4 fragColor;

void main(void)
{
    fragColor = vec4(1.);
}

#ifdef GL_ES
precision highp float;
#endif

uniform float time;
uniform vec2 resolution;
uniform vec2 mouse;
uniform vec3 spectrum;

uniform sampler2D texture0;
uniform sampler2D texture1;
uniform sampler2D texture2;
uniform sampler2D texture3;
uniform sampler2D prevFrame;
uniform sampler2D prevPass;

varying vec3 v_normal;
varying vec2 v_texcoord;

void main(void)
{
    gl_FragColor = vec4(1.);
}

